/**
 * 明暗主题切换按钮（2026-11-27）。
 *
 * 🔴 SSR 安全（Gatsby 静态站）：initState 一律 null，不读 localStorage / matchMedia。
 *    React hydration 完成后在 useEffect 里读实际偏好 → setState → classList 同步。
 *    首屏防闪由 html.js 的同步脚本负责（在 CSS 之前挂 .dark），本组件只管运行时切换。
 *    若这里在渲染期读 window，SSR 输出的按钮状态与客户端不一致 ⇒ hydration mismatch。
 *
 * 🔴 契约（公约 shell-ui-contract.md §2.4 + 用户 2026-11-27 裁决）：只有 light / dark
 *    两种主题，不提供 system 第三态，也**不监听 prefers-color-scheme 变化**：
 *    系统偏好只在首屏/挂载时读一次作为默认值，之后完全由 localStorage 手动覆盖决定。
 *    文案表示「将要切换到的目标」（当前暗 → sun + "Switch to light theme"）。
 *    localStorage key 独立（whaleal-www-theme），不与 console / cart-ui 共享。
 */
import React, { useEffect, useState } from 'react';
import { useI18n } from '../../i18n';
import './theme-toggle.css';

const STORAGE_KEY = 'whaleal-www-theme';

export default function ThemeToggle() {
  const { t } = useI18n();
  // null = 尚未在客户端解析；SSR 与首屏 hydration 都渲染「无图标」占位，
  // useEffect 后才有确定状态，避免前后端 markup 不一致。
  const [isDark, setIsDark] = useState(null);

  useEffect(() => {
    let dark = false;
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      dark =
        saved === 'dark' ||
        (saved !== 'light' &&
          window.matchMedia('(prefers-color-scheme: dark)').matches);
    } catch (e) {
      dark = false; // 隐私模式兜底：保持亮色
    }
    setIsDark(dark);
    document.documentElement.classList.toggle('dark', dark);
  }, []);

  const toggle = () => {
    // 🔴 以 DOM 实际状态为真源，不用 `!isDark`：首屏脚本已按 localStorage / 系统偏好
    //    挂好 .dark，而 isDark 在 useEffect 前是 null。`!null === true` 会把
    //    「点一下翻转」变成「强制切暗」，与用户看到的实际主题相反。
    const next = !document.documentElement.classList.contains('dark');
    setIsDark(next);
    document.documentElement.classList.toggle('dark', next);
    try {
      localStorage.setItem(STORAGE_KEY, next ? 'dark' : 'light');
    } catch (e) {
      // 隐私模式：偏好不持久化，但本次切换仍生效
    }
  };

  // 🔴 null 时给稳定兜底名（默认按亮色 ⇒ 提示切到深色）：SSR 与客户端首帧都走
  //    这一支，markup 完全一致；useEffect 后再按真实偏好更新。空 aria-label 会
  //    让按钮在首屏 / 无 JS 时成为「无名按钮」（WCAG 4.1.2 Name, Role, Value）。
  const label = isDark === true ? (t.theme?.toggleToLight || '') : (t.theme?.toggleToDark || '');

  return (
    <button
      type="button"
      className="theme-toggle"
      onClick={toggle}
      aria-label={label}
      title={label}
      // null 时不输出 pressed，避免谎报「未按下」（首屏可能已是暗色）；
      // SSR 省略该属性，客户端首帧同样省略 ⇒ hydration 一致。
      aria-pressed={isDark === null ? undefined : isDark}
    >
      {isDark === null ? (
        <span className="theme-toggle-icon" aria-hidden="true" />
      ) : isDark ? (
        <svg className="theme-toggle-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
          <circle cx="12" cy="12" r="4" />
          <path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41" />
        </svg>
      ) : (
        <svg className="theme-toggle-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
          <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
        </svg>
      )}
    </button>
  );
}
